// The siege frame of the visual overhaul (proposal section 4): the keep, towers, gate arches,
// parapet, hedges and cobbled lanes are drawn in code in the sticker style (plum ink outline, flat
// fill, one cel tone), skinned per chapter from CHAPTER_SKINS. What code cannot draw well is
// generated by tools/pipeline.mjs as `env.*` sprites (FRAME_ASSETS). Pure data, plus the small
// pure rules the renderer and the HUD share (chapter skin, gate preview chips, braziers, ticks).
import { BOARD_HALF, BOARD_SPAN, DESIGN_CELL, DICE, FIELD, GRID, GRID_TOP, cellX, laneX } from '../config.js';
import { CHAPTERS } from '../sim/enemies.js';
import { mix, tone } from './tokens.js';

/**
 * The frame's parts sized by the board (v2.1, docs/v2/SPEC-v2.1.md section 1), as shares of a board cell:
 * they follow the cell as the board grows (4×4: cell 2, 5×5: 1.6, 6×6: 1.33) and keep their 4×4 look. A lane
 * strip is `lane` of a cell wide (the hedge takes the rest), a gate arch's opening `gateR` (its radius) in a
 * stone ring `gateRing` thick, a merlon `merlon` wide, a hedge's scallop `scallop` across.
 */
export const CELL_SHARE = { lane: 0.725, gateR: 0.29, gateRing: 0.16, merlon: 0.42, scallop: 0.055 };

/** The x of column (or lane) `c` on a board whose cells are `cell` world units: cellX for any cell (the grow moment eases it). */
export const cellXAt = (c, cell = GRID.cell) => -BOARD_HALF + cell * (c + 0.5);
/** The y of row `r` on a board whose cells are `cell` world units. */
export const cellYAt = (r, cell = GRID.cell) => cell * (r + 0.5);

/**
 * How big the things that stand in a lane are drawn: foes, summoned pets, the braziers and the gates' chips.
 * 1 on the 4×4 board; on a bigger one halfway between that and the cell's own shrink (0.9 at 5×5, 0.83 at
 * 6×6), so they stay readable on a phone yet never crowd the narrower lanes. Drawing only: the sim's sizes
 * and distances do not change.
 */
export const laneFit = (cell = GRID.cell) => (1 + cell / DESIGN_CELL) / 2;

/**
 * The board's grow moment (v2.1): `time` s, eased in and out (growEase). The keep's grid zooms out: the
 * tiles and their pits ease to their new places and sizes, a new column of pits slides in under the keep's
 * right wall and a new row under the parapet, and each new lane (its strip, gate and brazier) slides in
 * from behind the right tower while the old lanes close up to the left.
 */
export const GROW = { time: 0.6 };
/** The grow moment's easing (0–1 → 0–1): cubic in and out, so it starts and settles softly. */
export const growEase = (t) => {
  const k = Math.max(0, Math.min(1, t));
  return k < 0.5 ? 4 * k * k * k : 1 - (-2 * k + 2) ** 3 / 2;
};

/**
 * Where piece `i` (a column or lane, or a row) of a board growing from `from` to `to` cells across is drawn,
 * `k` (0–1, eased) of the way, as `at(i, cell)` places it (cellXAt, cellYAt): an old one (i < from) on the
 * cell between the two boards'; a new one slides in from out of sight, its near edge (`half` from its centre)
 * past `hide` at the start, so it never peeks out early. → world x (or y)
 */
export function growPos(i, from, to, k, at, { hide = Infinity, half = 0 } = {}) {
  const c0 = BOARD_SPAN / from;
  const c1 = BOARD_SPAN / to;
  if (i < from) return at(i, c0 + (c1 - c0) * k);
  const end = at(i, c1);
  const start = Math.max(at(i, c0), hide + half);
  return start + (end - start) * k;
}

/**
 * Material roles per chapter: stone (base, shade, light), trim (timber), hedge, lane sand (calm
 * centre) and its cobble edge, accent. The frame uses no other colours: floor and pit (the dark
 * keep), opening (the gates' dark), iron (braziers, portcullis), flame (outer, inner), banner,
 * gold, sky (the painted backdrop's fallback gradient, top to bottom), ridge (the far treeline's
 * fallback silhouette) and slate (the HUD's stone: face, light, dark; cream text sits on it).
 */
export const CHAPTER_SKINS = {
  forest: {
    stone: ['#C9C6B8', '#9FA092', '#E6E4D8'], trim: '#8A6A43', hedge: '#4A5A52', lane: '#D9C7A3', cobble: '#C2AE88', accent: '#7A9A5A',
    backdrop: 'env.forest.backdrop', ridge: 'env.forest.ridge', decor: ['env.moss', 'env.mushroom'],
    floor: '#3E3C58', pit: '#35334E', opening: '#1F1826', iron: '#3B3440', flame: ['#FF7A2E', '#FFC94A'], banner: '#B23A3A', gold: '#FFCF4A',
    sky: ['#2A4466', '#1F3352', '#15223A'], ridgeTone: '#1D302F', slate: ['#5E625C', '#7C8079', '#3F433E'],
  },
  fareast: {
    stone: ['#CFC8BC', '#A79F92', '#EAE4D9'], trim: '#B2574E', hedge: '#3F5A48', lane: '#D9C7A3', cobble: '#C4AE8A', accent: '#B2574E',
    backdrop: 'env.fareast.backdrop', ridge: 'env.fareast.ridge', decor: ['env.lantern'],
    floor: '#3E3C58', pit: '#35334E', opening: '#1F1826', iron: '#3B3440', flame: ['#FF7A2E', '#FFC94A'], banner: '#B23A3A', gold: '#FFCF4A',
    sky: ['#4A3556', '#35263F', '#211829'], ridgeTone: '#2B1E2E', slate: ['#665B5E', '#83787B', '#463D40'],
  },
  peaks: {
    stone: ['#A8A3A6', '#7F7A80', '#CBC6C8'], trim: '#5A4A44', hedge: '#4A4A52', lane: '#CFC9BF', cobble: '#B5AEA4', accent: '#FF7A2E',
    backdrop: 'env.peaks.backdrop', ridge: 'env.peaks.ridge', decor: ['env.ember'],
    floor: '#3E3C58', pit: '#35334E', opening: '#1F1826', iron: '#3B3440', flame: ['#FF7A2E', '#FFC94A'], banner: '#B23A3A', gold: '#FFCF4A',
    sky: ['#38354A', '#29273A', '#1A1826'], ridgeTone: '#1F1D27', slate: ['#57525A', '#736D76', '#3A363D'],
  },
};

/**
 * The grounds a foe must read on in each chapter (tools/silhouette-check.py's figure-ground gate):
 * the lane sand, the hedge and the keep floor, taken from the skins so the two cannot drift.
 */
export const CHAPTER_GROUNDS = Object.fromEntries(Object.entries(CHAPTER_SKINS).map(([k, s]) => [k, { lane: s.lane, hedge: s.hedge, keep: s.floor }]));

/** The ink and cream every skin shares (src/art/tokens.js). */
export const FRAME_INK = '#2b1d2e';
export const FRAME_CREAM = '#fffaf2';

