/**
 * Where the frame's pieces sit, in world units (x right, y up; the board is x −4..4, y 0..8 at every
 * size). The pieces sized by the board follow its cell (CELL_SHARE; read at use time, as GRID.cell is):
 * the values below are the 4×4 board's.
 * - lanes: 1.45 wide on the column centres (0.725 cell); the calm centre is the middle 60%, cobbles
 *   the outer 20% bands; the lane runs from the gate's sill down to the parapet's wall top.
 * - hedges fill the gaps between lanes (0.55) and the strips outside the outer lanes up to the
 *   towers' inner edges (x ±4.2), which is also where the namecard rail starts.
 * - gate arches: one per lane, opening radius 0.58 around the springing point (y 17.15), a stone
 *   ring 0.32 thick; the sill is at 16.55 (foes appear at FIELD.spawnY 16.9, inside the arch).
 * - parapet: the wall from the keep's top edge (8.28) to 8.8, a merlon per column (0.84 wide) up to
 *   9.2, a brazier on each merlon.
 * - keep: the dark floor is the board plus `pad`, the stone ring `wall` thick, corner towers
 *   `tower` across. Pits are `pit` × cell, the size of a tile.
 */
export const FRAME_GEOM = {
  /** A lane strip's width (world units): CELL_SHARE.lane of the board's cell. */
  get laneW() {
    return CELL_SHARE.lane * GRID.cell;
  },
  calm: 0.6,
  towerIn: 4.2,
  towerW: 2.4, // a field tower's width; on a phone it runs off the screen's edge first
  gate: {
    y: 17.15,
    /** The arch's opening radius: CELL_SHARE.gateR of the board's cell. */
    get r() {
      return CELL_SHARE.gateR * GRID.cell;
    },
    /** Its stone ring: CELL_SHARE.gateRing of the board's cell. */
    get ring() {
      return CELL_SHARE.gateRing * GRID.cell;
    },
    sill: 16.55,
    wallTop: 17.55,
  },
  towerTop: 18.75,
  parapet: {
    base: GRID_TOP + 0.28,
    wall: GRID_TOP + 0.8,
    merlon: GRID_TOP + 1.2,
    /** A merlon's width: CELL_SHARE.merlon of the board's cell. */
    get w() {
      return CELL_SHARE.merlon * GRID.cell;
    },
  },
  keep: { pad: 0.28, wall: 0.22, tower: 0.86 },
  pit: 0.9,
  // the deck row: dice `die` wide, `gap` apart; the next die's slot is `slot` wide (room for "at 512"
  // at 12 px on a 360 px phone); `end` is the timber rail past the dice and the slot
  deck: { y: -1.05, die: 0.72, gap: 0.2, slot: 2.1, end: 0.25 }, // slot: "at 512" at 14 px on a 360 px phone
  // the namecard rail hangs on the right tower, from the gate wall's top to the parapet
  rail: { top: 18.05, bottom: GRID_TOP + 0.8 },
};

/**
 * The namecard rail in CSS px (src/kv/namecards.js railLayout; src/render/stage.js fitU keeps room
 * for the narrowest one): cards are never under `card` px (the touch-target floor), with `margin`
 * px between a card's ink ring and the tower's edges.
 */
export const RAIL_PX = { card: 44, margin: 2 };

/**
 * The deck row under the keep: the dice and, while a die is still to come, the slot that names the
 * block bringing it, centred together. The renderer's dice (src/render/deck.js) and the timber rail
 * (src/render/frame.js) both place themselves from this. → world x of { x0: the first die's
 * centre, slotX: the slot's left edge (null without one), left, right: the rail's ends }
 */
export function deckRow(dice, withSlot = false) {
  const { die, gap, slot, end } = FRAME_GEOM.deck;
  const w = dice * die + Math.max(0, dice - 1) * gap;
  const total = w + (withSlot ? gap + slot : 0);
  const x0 = -total / 2;
  return { x0: x0 + die / 2, slotX: withSlot ? x0 + w + gap : null, left: x0 - end, right: total / 2 + end };
}

/**
 * A lane's tones (Rev 2, the truth composite): the calm centre is the lane sand with two large,
 * low-contrast patch tones (within 4 L* of it); the outer bands carry the cobbles on a grout
 * between sand and cobble, outlined a step darker.
 */
export function laneTones(skin) {
  return {
    base: skin.lane,
    patchLight: tone(skin.lane, 0.12),
    patchDark: tone(skin.lane, -0.035),
    grout: mix(skin.lane, skin.cobble, 0.55),
    cobble: skin.cobble,
    cobbleLight: tone(skin.cobble, 0.16),
    cobbleLine: mix(skin.cobble, FRAME_INK, 0.45),
  };
}

/**
 * A hedge's tones: the dark ground foes read on, and the one lit scallop along its left edge (the
 * key light is upper left), a calm cel tone a few L* lighter.
 */
export const hedgeTones = (skin) => ({ base: skin.hedge, scallop: tone(skin.hedge, 0.06) });

/**
 * The far layers have no part in the fight, so they keep only their largest shapes and their
 * colour mood. The painted backdrop is drawn once per chapter at 1/`shrink` of its size (the linear
 * filter draws it back up soft), blurred once, desaturated by `desat`, pulled toward the chapter's
 * sky gradient by `flatten` and dimmed by `dim` (softenBackdrop). The ridge strip is one flat tone,
 * `ridge` of the way from the ridge's tone to the sky's middle (ridgeFlat), its silhouette also
 * drawn from 1/`shrink` of its size.
 */
export const FAR = { shrink: 8, desat: 0.6, flatten: 0.5, dim: 0.3, ridge: 0.5 };

const rgbOf = (hex) => {
  const n = parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
};

/** The sky gradient's colour at t (0 at the top, 1 at the bottom), as [r, g, b]. */
export function skyAt(skin, t) {
  const stops = skin.sky;
  const f = Math.max(0, Math.min(1, t)) * (stops.length - 1);
  const i = Math.min(stops.length - 2, Math.floor(f));
  const [a, b] = [rgbOf(stops[i]), rgbOf(stops[i + 1])];
  return a.map((v, c) => v + (b[c] - v) * (f - i));
}

/** The ridge strip's one flat tone. */
export const ridgeFlat = (skin) => mix(skin.ridgeTone, skin.sky[1], FAR.ridge);

/**
 * The far layer from a painting's pixels (RGBA, w × h, already shrunk; changed in place and
 * returned): blurred once ([1 2 1] across, then down), desaturated, pulled toward the sky gradient
 * and dimmed, by `far`. In any row it keeps at most (1 − flatten)(1 − dim) of the painting's contrast.
 */
export function softenBackdrop(px, w, h, skin, far = FAR) {
  const at = (x, y) => (Math.min(h - 1, Math.max(0, y)) * w + Math.min(w - 1, Math.max(0, x))) * 4;
  const across = new Float32Array(px.length);
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      for (let c = 0; c < 3; c++) across[at(x, y) + c] = (px[at(x - 1, y) + c] + 2 * px[at(x, y) + c] + px[at(x + 1, y) + c]) / 4;
    }
  }
  const v = [0, 0, 0];
  for (let y = 0; y < h; y++) {
    const sky = skyAt(skin, h > 1 ? y / (h - 1) : 0);
    for (let x = 0; x < w; x++) {
      const i = at(x, y);
      for (let c = 0; c < 3; c++) v[c] = (across[at(x, y - 1) + c] + 2 * across[i + c] + across[at(x, y + 1) + c]) / 4;
      const l = 0.2126 * v[0] + 0.7152 * v[1] + 0.0722 * v[2];
      for (let c = 0; c < 3; c++) {
        const grey = v[c] + (l - v[c]) * far.desat;
        px[i + c] = (grey + (sky[c] - grey) * far.flatten) * (1 - far.dim);
      }
      px[i + 3] = 255;
    }
  }
  return px;
}

/** The chapter skin for a key ('forest' | 'fareast' | 'peaks'); unknown keys get the forest. */
export const skinFor = (key) => CHAPTER_SKINS[key] ?? CHAPTER_SKINS.forest;

/** A chapter's key from its key or its display name ('Eternal Forest' → 'forest'). */
export function chapterKeyFor(chapter) {
  if (!chapter) return 'forest';
  if (CHAPTER_SKINS[chapter]) return chapter;
  const name = typeof chapter === 'object' ? chapter.key ?? chapter.name : chapter;
  if (CHAPTER_SKINS[name]) return name;
  return CHAPTERS.find((c) => c.name === name)?.key ?? 'forest';
}

/**
 * The gates' next-wave chips: one per lane the wave comes down, with the lane's most common foe
 * and how many foes come that way. On the boss's lane the chip is the boss, and the count is the
 * foes that come with it. A wave of { spawns: [{ type, lane }], boss } (src/sim/enemies.js).
 * → [{ lane, type, count, boss }] by lane
 */
export function previewChips(wave) {
  if (!wave?.spawns?.length) return [];
  const lanes = new Map();
  for (const sp of wave.spawns) {
    let l = lanes.get(sp.lane);
    if (!l) lanes.set(sp.lane, (l = { lane: sp.lane, count: 0, types: new Map() }));
    l.count += 1;
    l.types.set(sp.type, (l.types.get(sp.type) ?? 0) + 1);
  }
  return [...lanes.values()]
    .sort((a, b) => a.lane - b.lane)
    .map(({ lane, count, types }) => {
      if (wave.boss && types.has(wave.boss)) return { lane, type: wave.boss, count: count - types.get(wave.boss), boss: true };
      let type = null;
      let most = 0;
      for (const [t, n] of types) if (n > most) [type, most] = [t, n]; // ties: the one that comes first
      return { lane, type, count, boss: false };
    });
}

/** Foes in a lane at which its brazier also smokes. */
export const PRESSURE_AT = 3;

/**
 * A brazier's state: 'cold' (unlit), 'warning' (lit: foes are coming down this lane, or will in the
 * next wave) or 'pressure' (lit and smoking: PRESSURE_AT foes or more in the lane, or the boss).
 * During a wave a lane is lit while it has foes alive or still due out of its gate (dueByLane), so
 * the brazier does not go dark when the wave starts, nor between one foe's death and the next spawn.
 * state = { phase, lanes (the wave's lanes), perLane (foes alive per lane), due (foes still to
 * spawn per lane), bossLane }
 */
export function brazierState(lane, state) {
  if (!state) return 'cold';
  const busy = state.perLane?.[lane] ?? 0;
  if (state.phase === 'wave') {
    if (busy >= PRESSURE_AT || (busy > 0 && state.bossLane === lane)) return 'pressure';
    return busy > 0 || (state.due?.[lane] ?? 0) > 0 ? 'warning' : 'cold';
  }
  if (state.phase === 'prep' || state.phase === 'break') return state.lanes?.includes(lane) ? 'warning' : 'cold';
  return 'cold';
}

/**
 * Foes still due out of each lane's gate this wave: the wave's spawns the run has not sent yet.
 * The run sends `wave.spawns` in order, and `left` counts those still to come plus the foes alive
 * (src/sim/run.js), so the last `left − alive` spawns are the ones due.
 * run = { phase, wave: { spawns: [{ lane }] }, left, defense: { aliveCount } } → [count per lane]
 */
export function dueByLane(run) {
  const out = new Array(FIELD.lanes).fill(0);
  if (run?.phase !== 'wave') return out;
  const spawns = run.wave?.spawns ?? [];
  const alive = run.defense?.aliveCount ?? (run.enemies ?? []).filter((e) => !e.dead && !e.gone).length;
  const due = Math.max(0, Math.min(spawns.length, (run.left ?? 0) - alive));
  for (let i = spawns.length - due; i < spawns.length; i++) {
    const lane = spawns[i].lane;
    if (lane >= 0 && lane < out.length) out[lane] += 1;
  }
  return out;
}

/** Seconds a brazier keeps its level after its lane calms down (its last foe fell, the crowd thinned). */
export const BRAZIER_HOLD = 1.5;
const LEVEL = { cold: 0, warning: 1, pressure: 2 };

/**
 * One frame of a brazier as shown: it rises to a new state at once and keeps a higher one for
 * BRAZIER_HOLD seconds after the lane calms down, so it never blinks with each kill and spawn.
 * shown = the last frame's { st, hold } (or null), st = brazierState now, dt in seconds → { st, hold }
 */
export function holdBrazier(shown, st, dt, hold = BRAZIER_HOLD) {
  if (!shown || LEVEL[st] >= LEVEL[shown.st]) return { st, hold };
  const left = shown.hold - dt;
  return left > 0 ? { st: shown.st, hold: left } : { st, hold };
}

/**
 * Tick marks up each lane, one per cell: the board's cell lines carried up the field (4×4: y 10, 12, 14,
 * 16; 6×6: 9.33 … 16), for a board whose cells are `cell` world units (the grow moment eases it).
 */
export function laneTicks(cell = GRID.cell) {
  const ticks = [];
  for (let k = 1; GRID_TOP + k * cell < FRAME_GEOM.gate.sill; k++) ticks.push(GRID_TOP + k * cell);
  return ticks;
}

/**
 * The ticks a selected block's range lights: the lanes it covers, the ticks inside the band.
 * range = { x, y, shoot: { reach, lanes } | { radius } } in world units, as scenery.showRange gets it.
 * → [{ lane, y }]
 */
export function litTicks(range) {
  if (!range?.shoot) return [];
  const { x, y, shoot } = range;
  const ticks = laneTicks();
  const out = [];
  if (shoot.radius != null) {
    for (let l = 0; l < FIELD.lanes; l++) for (const ty of ticks) if (Math.hypot(laneX(l) - x, ty - y) <= shoot.radius) out.push({ lane: l, y: ty });
    return out;
  }
  const lane = laneOf(x);
  const top = Math.min(FIELD.spawnY, y + shoot.reach);
  const bottom = Math.max(FIELD.gateY, y - shoot.reach);
  const n = shoot.lanes ?? 0;
  for (let l = Math.max(0, lane - n); l <= Math.min(FIELD.lanes - 1, lane + n); l++) for (const ty of ticks) if (ty >= bottom && ty <= top) out.push({ lane: l, y: ty });
  return out;
}

/** The lane (column) nearest to world x. */
export const laneOf = (x) => Math.max(0, Math.min(FIELD.lanes - 1, Math.round((x - cellX(0)) / GRID.cell)));

/** The value of the block that unlocks the next die (64, 256, 512), or null once every die is in. */
export function nextDieAt(maxTier) {
  const tier = DICE.unlockTiers.find((t) => t > (maxTier ?? 0));
  return tier ? 2 ** tier : null;
}

/** Deterministic 0..1 noise for decor placement (no Math.random: the frame is the same every build). */
export function hash01(i, j = 0) {
  let h = Math.imul(i + 0x9e3779b9, 0x85ebca6b) ^ Math.imul(j + 0x7f4a7c15, 0xc2b2ae35);
  h ^= h >>> 15;
  h = Math.imul(h, 0x2c1b3c6d);
  return ((h ^ (h >>> 12)) >>> 0) / 4294967296;
}

/**
 * Chapter decor is a whisper of the chapter, never a rival to a foe: one prop on each outer hedge
 * (beside a tower, never between two lanes), `size` across so it stays inside its hedge, drawn at
 * `alpha` and tinted `tint` of the way from the hedge to cream.
 */
export const DECOR = { size: 0.3, alpha: 0.5, tint: 0.55 };

/**
 * Chapter decor on the outer hedges, placed by hash: one spot on each.
 * → [{ id, strip, x, y, s }] (world units; s = size)
 */
export function decorSpots(chapterKey) {
  const ids = skinFor(chapterKey).decor ?? [];
  if (!ids.length) return [];
  const seed = { forest: 11, fareast: 23, peaks: 37 }[chapterKey] ?? 5;
  const { parapet, gate } = FRAME_GEOM;
  const out = [];
  hedgeStrips().forEach((st, k) => {
    if (!st.outer) return;
    const t = 0.15 + 0.7 * hash01(seed + k, 0);
    const id = ids[Math.floor(hash01(seed + 7 * k, 31) * ids.length)];
    out.push({ id, strip: k, x: (st.x0 + st.x1) / 2, y: parapet.wall + 0.55 + t * (gate.sill - parapet.wall - 1.1), s: DECOR.size });
  });
  return out;
}

/** The hedge strips between and outside the lanes: [{ x0, x1, outer }] in world x. */
export function hedgeStrips() {
  const half = FRAME_GEOM.laneW / 2;
  const strips = [{ x0: -FRAME_GEOM.towerIn, x1: laneX(0) - half, outer: true }];
  for (let l = 0; l < FIELD.lanes - 1; l++) strips.push({ x0: laneX(l) + half, x1: laneX(l + 1) - half, outer: false });
  strips.push({ x0: laneX(FIELD.lanes - 1) + half, x1: FRAME_GEOM.towerIn, outer: true });
  return strips;
}
